const items = $input.all();

return items.map((item, index) => {
  const content = item.json?.choices?.[0]?.message?.content;

  if (typeof content !== 'string' || !content.trim()) {
    throw new Error(`FASTGPT_EMPTY_CONTENT item=${index}`);
  }

  let validatedLead;

  try {
    validatedLead = JSON.parse(content.trim());
  } catch (error) {
    throw new Error(
      `FASTGPT_INVALID_JSON item=${index}: ${error.message}`
    );
  }

  return {
    json: {
      fastgptChatId: item.json.id ?? null,
      validatedLead
    },
    pairedItem: {
      item: index
    }
  };
});

const items = $input.all();

function stableJsonValue(value) {
  if (Array.isArray(value)) {
    return value.map(stableJsonValue);
  }

  if (!value || typeof value !== 'object') {
    return value;
  }

  return Object.fromEntries(
    Object.entries(value)
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([key, nested]) => [key, stableJsonValue(nested)])
  );
}

function normalizedPayload(payload) {
  return Object.fromEntries(
    Object.entries(payload)
      .filter(([, value]) => value !== undefined)
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([key, value]) => [key, stableJsonValue(value)])
  );
}

return items.map((item, index) => {
  const payload = Object.fromEntries(
    Object.entries(item.json)
      .filter(([key]) => !['idempotencyKey', 'payloadHash'].includes(key))
  );

  const canonicalPayload = normalizedPayload(payload);
  const canonicalJson = JSON.stringify(canonicalPayload);

  return {
    json: {
      canonicalPayload,
      canonicalJson
    },
    pairedItem: {
      item: index
    }
  };
});

const items = $input.all();

const allowedBusinessFields = [
  'companyName',
  'contactName',
  'phone',
  'email',
  'source',
  'sourceUrl',
  'searchKeyword',
  'aiScore',
  'profile',
  'sourceModelVersion',
  'extractorVersion',
  'sourceSystem',
  'externalLeadId',
];

return items.map((item, index) => {
  const {
    canonicalPayload,
    payloadHash,
    idempotencyDigest,
  } = item.json;

  if (
    !canonicalPayload ||
    typeof canonicalPayload !== 'object' ||
    Array.isArray(canonicalPayload)
  ) {
    throw new Error(`LEAD_CANONICAL_PAYLOAD_INVALID item=${index}`);
  }

  if (!/^[a-f0-9]{64}$/.test(String(payloadHash ?? ''))) {
    throw new Error(`LEAD_PAYLOAD_HASH_INVALID item=${index}`);
  }

  if (!/^[a-f0-9]{64}$/.test(String(idempotencyDigest ?? ''))) {
    throw new Error(`LEAD_IDEMPOTENCY_DIGEST_INVALID item=${index}`);
  }

  const idempotencyKey = `lead-v2-${idempotencyDigest}`;

  const finalItem = {
    idempotencyKey,
    payloadHash,
  };

  for (const key of allowedBusinessFields) {
    const value = canonicalPayload[key];

    // undefined 不进入 3012。
    if (value === undefined) continue;

    // 3012 的 optional string 不接受 null。
    if (
      value === null &&
      ['contactName', 'phone', 'email'].includes(key)
    ) {
      continue;
    }

    finalItem[key] = value;
  }

  if (
    typeof finalItem.companyName !== 'string' ||
    !finalItem.companyName.trim()
  ) {
    throw new Error(`LEAD_COMPANY_NAME_INVALID item=${index}`);
  }

  if (!['BAIDU_SEARCH', 'MANUAL', 'OTHER'].includes(finalItem.source)) {
    throw new Error(`LEAD_SOURCE_INVALID item=${index}`);
  }

  if (
    idempotencyKey.length < 16 ||
    idempotencyKey.length > 191 ||
    !/^[A-Za-z0-9][A-Za-z0-9._:-]*$/.test(idempotencyKey)
  ) {
    throw new Error(`LEAD_IDEMPOTENCY_KEY_INVALID item=${index}`);
  }

  return {
    json: finalItem,
    pairedItem: {
      item: index,
    },
  };
});

const items = $input.all();

if (items.length < 1 || items.length > 20) {
  throw new Error(`LEAD_UPSERT_ITEMS_COUNT_INVALID count=${items.length}`);
}

return [
  {
    json: {
      items: items.map((item) => item.json),
    },
  },
];

return (function contactEntryGate() {
  const config = $('Search Config').first().json;
  const phoneValid = (value) => typeof value === 'string' && /^\+?[0-9][0-9 ()-]{5,30}[0-9]$/.test(value.trim()) && value.replace(/\D/g, '').length >= 7 && value.replace(/\D/g, '').length <= 15;
  const emailValid = (value) => typeof value === 'string' && value.trim().length <= 191 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
  return $input.all().map((item, index) => {
    const validatedLead = { ...item.json.validatedLead };
    if (phoneValid(validatedLead.phone)) validatedLead.phone = validatedLead.phone.trim();
    else delete validatedLead.phone;
    if (emailValid(validatedLead.email)) validatedLead.email = validatedLead.email.trim();
    else delete validatedLead.email;
    if (typeof validatedLead.contactName === 'string' && validatedLead.contactName.trim()) validatedLead.contactName = validatedLead.contactName.trim();
    else delete validatedLead.contactName;
    const aiScore = Number(validatedLead?.aiScore);
    const hasContact = phoneValid(validatedLead?.phone) || emailValid(validatedLead?.email);
    const shouldWrite = Number.isInteger(aiScore) && aiScore >= 80 && hasContact;
    const shouldSearch = config.contact_search_enabled === true
      && Number.isInteger(aiScore)
      && aiScore > Number(config.contact_search_score_threshold)
      && !hasContact;
    return { json: {
      ...item.json,
      validatedLead,
      shouldWrite,
      shouldSearch,
      contactSearchRound: 0,
      contactSearchMaxRounds: Math.min(Number(config.contact_search_max_rounds), 3),
      previousQueries: [],
      excludedResults: [],
      status: shouldSearch ? 'CONTACT_SEARCH_STARTED' : 'CONTACT_SEARCH_NOT_REQUIRED',
      lastFailureStatus: null,
    }, pairedItem: { item: index } };
  });
})();

return (function finalLeadEntryGate() {
  const phoneValid = (value) => typeof value === 'string' && /^\+?[0-9][0-9 ()-]{5,30}[0-9]$/.test(value.trim()) && value.replace(/\D/g, '').length >= 7 && value.replace(/\D/g, '').length <= 15;
  const emailValid = (value) => typeof value === 'string' && value.trim().length <= 191 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
  return $input.all().map((item, index) => {
    const lead = item.json.validatedLead;
    const shouldWrite = Number.isInteger(Number(lead?.aiScore)) && Number(lead.aiScore) >= 80 && (phoneValid(lead?.phone) || emailValid(lead?.email));
    return { json: { ...item.json, shouldWrite, status: shouldWrite ? item.json.status : 'CONTACT_NOT_VERIFIED' }, pairedItem: { item: index } };
  });
})();

return (function terminalLead() {
  return $input.all().map((item, index) => ({ json: { ...item.json, shouldWrite: false, shouldSearch: false }, pairedItem: { item: index } }));
})();

return (function exhaustedLead() {
  return $input.all().map((item, index) => ({ json: {
    ...item.json,
    shouldWrite: false,
    shouldSearch: false,
    verified: false,
    status: 'CONTACT_ENRICHMENT_EXHAUSTED',
  }, pairedItem: { item: index } }));
})();

return (function validateLeadMcpResult() {
  return $input.all().map((item, index) => {
    const result = item.json?.result;
    const structured = result?.structuredContent;
    const leadWriteResult = structured?.data?.items?.[0];
    const businessSuccess = result?.isError !== true
      && structured?.ok === true
      && typeof leadWriteResult?.id === 'string';
    if (!businessSuccess) {
      const errorCode = typeof structured?.error?.code === 'string'
        ? structured.error.code
        : 'MCP_RESPONSE_INVALID';
      throw new Error(`LEAD_MCP_WRITE_FAILED item=${index} code=${errorCode}`);
    }
    return {
      json: { ...item.json, leadWriteResult },
      pairedItem: { item: index },
    };
  });
})();

